html:
{#- Kanban Card (Shop Floor): the card that travels with its container. The card id is printed as a QR code (Frappe's QR helper, exposed by automotive_manufacturing's jinja hook) and in large text; cut along the border. Black on white. -#}
{%- macro esc(value) -%}{%- if value is defined and value is not none -%}{{ value|e }}{%- endif -%}{%- endmacro -%}
{%- macro num(value) -%}
{%- set n = frappe.utils.flt(value) -%}
{%- if n == frappe.utils.cint(n) -%}{{ frappe.utils.fmt_money(n, 0) }}{%- else -%}{{ frappe.format(n, {"fieldtype": "Float"}) }}{%- endif -%}
{%- endmacro -%}
{%- set kl = frappe.db.get_value("Kanban Loop", doc.kanban_loop, ["company", "production_line", "supply_type", "line_side_warehouse", "source_warehouse", "supplier", "container_qty", "number_of_cards"], as_dict=True) or {} -%}
{%- set item = frappe.db.get_value("Item", doc.item_code, ["item_name", "stock_uom"], as_dict=True) if doc.item_code else none -%}
{%- set qr = automotive_qr_code(doc.card_id) if automotive_qr_code is defined else "" -%}
<style>
	@page { size: A4; margin: 15mm; }
	.hn-doc { color: #000; background: #fff; font-size: 9pt; line-height: 1.35; }
	.hn-doc table { width: 100%; border-collapse: collapse; }
	.hn-doc th, .hn-doc td { color: #000; background: #fff; border: 1px solid #000; padding: 1.2mm 1.8mm; text-align: left; vertical-align: top; }
	.hn-doc .hn-head { margin-bottom: 4mm; border-bottom: 0.6mm solid #000; }
	.hn-doc .hn-head td { border: 0; padding: 0 0 2mm 0; vertical-align: bottom; }
	.hn-doc .hn-company { font-size: 10pt; font-weight: bold; }
	.hn-doc .hn-title { font-size: 16pt; font-weight: bold; margin-top: 1mm; }
	.hn-doc .hn-right { text-align: right; }
	.hn-doc .hn-label { font-size: 7.5pt; }
	.hn-doc .hn-docno { font-size: 12pt; font-weight: bold; font-family: monospace; }
	.hn-doc .hn-state { display: inline-block; margin-top: 1mm; padding: 0.5mm 2mm; border: 0.5mm solid #000; font-weight: bold; }
	.hn-doc .hn-meta th { width: 18%; }
	.hn-doc .hn-meta td { width: 32%; }
	.hn-doc .hn-section { margin: 5mm 0 1.5mm 0; font-size: 10.5pt; font-weight: bold; }
	.hn-doc .hn-lines { margin-top: 4mm; }
	.hn-doc .hn-lines thead { display: table-header-group; }
	.hn-doc .hn-lines th { border-bottom: 0.5mm solid #000; }
	.hn-doc .hn-lines tr, .hn-doc .hn-sign, .hn-doc .hn-avoid { page-break-inside: avoid; break-inside: avoid; }
	.hn-doc .hn-num { text-align: right; white-space: nowrap; }
	.hn-doc .hn-strong { font-weight: bold; }
	.hn-doc .hn-mono { font-family: monospace; }
	.hn-doc .hn-summary { margin-top: 2mm; text-align: right; }
	.hn-doc .hn-card { border: 1.2mm solid #000; padding: 4mm 5mm; font-size: 10.5pt; page-break-inside: avoid; break-inside: avoid; }
	.hn-doc .hn-cardno { font-size: 18pt; font-weight: bold; }
	.hn-doc .hn-body td.hn-cell { border: 0; padding: 0; vertical-align: top; }
	.hn-doc .hn-body td.hn-qr-cell { border: 0; padding: 0 0 0 5mm; width: 48mm; text-align: right; vertical-align: top; }
	.hn-doc .hn-card .hn-meta th { width: 30%; }
	.hn-doc .hn-card .hn-meta td { width: 70%; }
	.hn-doc .hn-big { font-size: 14pt; font-weight: bold; }
	.hn-doc .hn-qr { width: 42mm; height: 42mm; }
	.hn-doc .hn-card-id { margin-top: 4mm; padding-top: 2mm; border-top: 0.6mm solid #000; text-align: center; font-family: monospace; font-size: 26pt; font-weight: bold; letter-spacing: 1px; }
</style>
<div class="hn-doc">
	<div class="hn-card">
		<table class="hn-head">
			<tr>
				<td>
					<div class="hn-company">{{ esc(kl.company) }}</div>
					<div class="hn-title">{{ _("Kanban Card") }}</div>
				</td>
				<td class="hn-right">
					<div class="hn-label">{{ _("Card No") }}</div>
					<div class="hn-cardno">{{ doc.card_no }} / {{ kl.number_of_cards or "" }}</div>
				</td>
			</tr>
		</table>
		<table class="hn-body">
			<tr>
				<td class="hn-cell">
					<table class="hn-meta">
						<tr>
							<th>{{ _("Loop Code") }}</th>
							<td class="hn-big hn-mono">{{ esc(doc.kanban_loop) }}</td>
						</tr>
						<tr>
							<th>{{ _("Item") }}</th>
							<td><span class="hn-big">{{ esc(doc.item_code) }}</span>{% if item and item.item_name and item.item_name != doc.item_code %}<br>{{ esc(item.item_name) }}{% endif %}</td>
						</tr>
						<tr>
							<th>{{ _("Container Qty") }}</th>
							<td class="hn-big">{{ num(kl.container_qty) }} {{ esc(item.stock_uom) if item else "" }}</td>
						</tr>
						{%- if kl.supply_type == "Supplier" %}
						<tr>
							<th>{{ _("Supplier") }}</th>
							<td class="hn-strong">{{ esc(frappe.db.get_value("Supplier", kl.supplier, "supplier_name") or kl.supplier) if kl.supplier else "" }}</td>
						</tr>
						{%- else %}
						<tr>
							<th>{{ _("Source Warehouse") }}</th>
							<td class="hn-strong">{{ esc(kl.source_warehouse) }}</td>
						</tr>
						{%- endif %}
						<tr>
							<th>{{ _("Line Side Warehouse") }}</th>
							<td class="hn-strong">{{ esc(kl.line_side_warehouse) }}</td>
						</tr>
						{%- if kl.production_line %}
						<tr>
							<th>{{ _("Production Line") }}</th>
							<td>{{ esc(kl.production_line) }}</td>
						</tr>
						{%- endif %}
					</table>
				</td>
				{%- if qr %}
				<td class="hn-qr-cell"><img class="hn-qr" src="{{ qr }}" alt="{{ esc(doc.card_id) }}"></td>
				{%- endif %}
			</tr>
		</table>
		<div class="hn-card-id">{{ esc(doc.card_id) }}</div>
	</div>
</div>
